import{_ as t,o,c as a,a2 as n}from"./chunks/framework.D_ZOUi6P.js";const g=JSON.parse('{"title":"Agent guide","description":"","frontmatter":{},"headers":[],"relativePath":"development/agents.md","filePath":"development/agents.md","lastUpdated":1793203876000}'),r={name:"development/agents.md"};function d(i,e,s,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-guide" tabindex="-1">Agent guide <a class="header-anchor" href="#agent-guide" aria-label="Permalink to &quot;Agent guide&quot;">​</a></h1><p>This page is the starting point for LLM agents working on Saluki, and for the humans directing them. It covers our policy on agent use, then points to the guidance for each part of the development process. Read it before starting any work, then read the linked pages relevant to your task.</p><h2 id="policy" tabindex="-1">Policy <a class="header-anchor" href="#policy" aria-label="Permalink to &quot;Policy&quot;">​</a></h2><p>Use of LLMs while working on Saluki is <strong>absolutely fine</strong>. This covers all aspects of working on the project: feature development, testing, debugging, and so on.</p><p>However, we don&#39;t allow fully autonomous or unsupervised development by agents. In practice:</p><ul><li>a human operator using LLMs as part of their workflow is <strong>OK</strong></li><li>setting up agents to run autonomously is <strong>NOT OK</strong></li><li>a human operator reviews every contribution before submission</li></ul><p>These rules have a single goal: keep human operators part of the development process, so that we maintain the quality of the software and don&#39;t lose understanding of what we&#39;re building.</p><h2 id="guiding-principles" tabindex="-1">Guiding principles <a class="header-anchor" href="#guiding-principles" aria-label="Permalink to &quot;Guiding principles&quot;">​</a></h2><ul><li>Top priorities are correctness, then performance, in that order.</li><li>Code should be maintainable and human-readable.</li><li>Documentation is crucial.</li><li>Development is a conversation, not a monologue. Communicate early and often, from ideation to execution, so that you and the human operator stay aligned on the current task: debugging an issue, adding a feature, or refactoring code.</li></ul><h2 id="documentation-lives-under-docs" tabindex="-1">Documentation lives under <code>docs/</code> <a class="header-anchor" href="#documentation-lives-under-docs" aria-label="Permalink to &quot;Documentation lives under `docs/`&quot;">​</a></h2><p>All documentation lives under <code>docs/</code>, and all development guidance lives under <code>docs/development/</code>. When you update documentation or propose a new page or section, it <strong>MUST</strong> go there. Don&#39;t add READMEs or other Markdown files next to code, and don&#39;t add guidance to the entrypoint files listed below. See <a href="./style-guide#where-documentation-lives">Where documentation lives</a> for the details.</p><h3 id="entrypoints" tabindex="-1">Entrypoints <a class="header-anchor" href="#entrypoints" aria-label="Permalink to &quot;Entrypoints&quot;">​</a></h3><p>Some files must stay where tooling expects to find them. They point into <code>docs/</code> instead of holding guidance:</p><table tabindex="0"><thead><tr><th>File</th><th>Read by</th><th>Contents</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>Agents that follow the <code>AGENTS.md</code> convention</td><td>Pointer to this page</td></tr><tr><td><code>.claude/CLAUDE.md</code></td><td>Claude Code</td><td>Imports this page</td></tr><tr><td><code>.agents/skills/*/SKILL.md</code>, symlinked from <code>.claude/skills</code></td><td>Agent skill discovery</td><td>Procedures; reference material lives in <code>docs/development/</code></td></tr><tr><td><code>codereview_guideline.md</code> files</td><td>The <code>/dd-review</code> workflow</td><td>Self-contained review prompts; see <a href="./code-review">Code review</a></td></tr><tr><td><code>test/antithesis/AGENTS.md</code></td><td>Agents working in <code>test/antithesis/</code></td><td>Antithesis workflow notes</td></tr></tbody></table><h2 id="project-map" tabindex="-1">Project map <a class="header-anchor" href="#project-map" aria-label="Permalink to &quot;Project map&quot;">​</a></h2><ul><li><code>bin/agent-data-plane</code>: the primary artifact of this project, a binary that runs alongside the Datadog Agent</li><li><code>bin/correctness</code>: tools for correctness and integration tests</li><li><code>lib/</code>: production frameworks and common code supporting <code>agent-data-plane</code></li><li><code>lib/datadog-agent/</code>: core Agent configuration and IPC protocols <ul><li><code>lib/datadog-agent/runtime</code>: the shared runtime for processes that act as a remote agent for the Datadog Agent, such as <code>agent-data-plane</code>: registration, configuration streaming, the workload provider, the status, flare, and telemetry services, the control plane workers, and the <code>RemoteAgent</code> startup facade</li></ul></li><li><code>docs/</code>: all documentation, published as the project&#39;s docs site</li><li><code>test/</code>: integration, correctness, benchmark, and Antithesis test cases</li></ul><h2 id="checking-your-work" tabindex="-1">Checking your work <a class="header-anchor" href="#checking-your-work" aria-label="Permalink to &quot;Checking your work&quot;">​</a></h2><p>The <code>Makefile</code> is authoritative for build commands. These checks get progressively deeper: use level 1 while editing Rust code, and work through the later levels when you think you&#39;re done.</p><ol><li><code>cargo check --workspace &amp;&amp; cargo check --workspace --tests</code>. At first this may be narrowed to the <code>--bin</code> or <code>--lib</code> you&#39;re working on, but run it on the whole workspace before moving on. Run the relevant tests with <code>cargo nextest run</code>, and always run <code>make fmt</code> when you&#39;re done editing.</li><li><code>make check-all</code> for lints, including Vale on documentation.</li><li><code>make test-all</code> for all unit tests.</li></ol><p>Use the <code>/panoramic</code> skill for correctness and integration testing.</p><h2 id="topics" tabindex="-1">Topics <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Read when</th></tr></thead><tbody><tr><td><a href="./style-guide">Style guide</a></td><td>Writing any code or documentation</td></tr><tr><td><a href="./conventions">Conventions</a></td><td>Making design choices; covers project-specific design rules and taste</td></tr><tr><td><a href="./common-language">Common language</a></td><td>Interpreting requirement levels such as <strong>MUST</strong> and <strong>SHOULD</strong></td></tr><tr><td><a href="./contributing">Contributing</a></td><td>Writing commits, opening pull requests, adding release notes, and addressing review feedback</td></tr><tr><td><a href="./code-review">Code review</a></td><td>Reviewing a change, or checking your own before opening a pull request</td></tr><tr><td><a href="./testing">Testing</a></td><td>Choosing which kind of test to write, and running test suites</td></tr><tr><td><a href="./testing-patterns">Testing patterns</a></td><td>Writing unit tests or property tests</td></tr><tr><td><a href="./configuration-system">Configuration system</a></td><td>Working on configuration, the schema overlay, or the configuration inventory</td></tr><tr><td><a href="#plans">Plans</a></td><td>Planning work that spans several pull requests</td></tr></tbody></table><p>For Antithesis work, read <code>test/antithesis/AGENTS.md</code>.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>Skills under <code>.agents/skills/</code> hold step-by-step procedures. Where a skill needs reference material, it links to a page in this guide.</p><table tabindex="0"><thead><tr><th>Skill</th><th>Purpose</th><th>Reference</th></tr></thead><tbody><tr><td><code>binary-size-analysis</code></td><td>Find what contributes to the size of the <code>agent-data-plane</code> binary</td><td></td></tr><tr><td><code>config-schema-update</code></td><td>Update the vendored Datadog configuration schema</td><td><a href="./configuration-system">Configuration system</a></td></tr><tr><td><code>config-system</code></td><td>Work on the configuration system</td><td><a href="./configuration-system">Configuration system</a></td></tr><tr><td><code>create-release-note</code></td><td>Write a release note fragment</td><td><a href="./contributing#release-notes">Release notes</a></td></tr><tr><td><code>external-pr-ci-trigger</code></td><td>Run CI for an external contributor&#39;s pull request (maintainers only)</td><td></td></tr><tr><td><code>panoramic</code></td><td>Run correctness and integration tests and read their results</td><td><a href="./testing">Testing</a></td></tr></tbody></table><h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans&quot;">​</a></h2><p>Write plans for work that spans several pull requests in <code>docs/development/plans/</code>, one file per effort. Plans aren&#39;t published to the docs site and aren&#39;t linted. Keep a plan current as work lands, move anything of lasting value into the relevant page of this guide, and delete the plan in the final pull request of the effort.</p>',28)])])}const p=t(r,[["render",d]]);export{g as __pageData,p as default};
